import {binaryAddress, deploymentConfig, enabledTab} from './presentation.js';
import {addr,ip,subnet,envelope,segments,validate} from './network.js';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),fmt=n=>n.toLocaleString('en-US');let config=deploymentConfig();let plan,poolId,selected,location='All locations',expanded=false,tab='explore';
const safeColor=p=>/^#[0-9a-f]{6}$/i.test(p.color)?p.color:'#6554c0';
const metric=(n,label)=>`<div class="metric"><strong>${n}</strong><span>${label}</span></div>`;
const detail=(label,value)=>`<div><dt>${label}</dt><dd>${esc(value)}</dd></div>`;
function setPlan(p){let errors=validate(p);if(errors.length)throw Error(errors.join('\n'));plan=p;poolId=p.pools[0].id;selected=p.pools[0].allocations[0]?.id;location='All locations';expanded=false;$('#planName').textContent=p.name;if(config.tabs.explore)render();if(config.tabs.guide)guide();if(config.tabs.practice)practice();setTab(tab);}
function setTab(t){t=enabledTab(config,t);tab=t;document.querySelectorAll('.tab').forEach(e=>e.hidden=e.id!==t);document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('selected',b.dataset.tab===t));if(t==='calculate')calculate();}
document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>setTab(b.dataset.tab));
function render(){let pool=plan.pools.find(p=>p.id===poolId),root=subnet(pool.cidr),segs=segments(pool),a=pool.allocations.find(x=>x.id===selected)||pool.allocations[0];selected=a?.id;let active=segs.filter(x=>x.status==='active').reduce((n,x)=>n+x.end-x.start+1,0),reserved=segs.filter(x=>['growth','reserved'].includes(x.status)).reduce((n,x)=>n+x.end-x.start+1,0);let locations=[...new Set(plan.pools.flatMap(p=>p.allocations.map(a=>a.location)))];
$('#explore').innerHTML=`<div class="heading"><div><h2>Your campus, one address space at a time.</h2><p class="sub">Select a pool, then click a subnet to uncover the reasoning.</p></div><span class="tag">✓ Plan validation passed</span></div><div class="pool-tabs">${plan.pools.map(p=>`<button class="pool-tab ${p.id===poolId?'active':''}" style="--accent:${safeColor(p)}" data-pool="${esc(p.id)}"><strong>${esc(p.name)}</strong><code>${esc(p.cidr)}</code></button>`).join('')}</div><div class="workspace"><div class="panel" style="--accent:${safeColor(pool)}"><div class="map-head"><div><h2>${esc(pool.name)}</h2><p class="sub"><code>${esc(pool.cidr)}</code> · ${fmt(root.size)} addresses</p></div><span class="tag">ADDRESS MAP</span></div><p class="sub">${esc(pool.description||'Select an allocation to inspect its address range.')}</p><div class="overview" aria-label="Proportional allocation overview">${segs.map(s=>`<button title="${esc(s.name)}: ${addr(s.start)} – ${addr(s.end)} (${fmt(s.end-s.start+1)} addresses)" style="width:${100*(s.end-s.start+1)/root.size}%;background:${s.status==='active'?safeColor(pool):s.status==='free'?'transparent':'#d9d0eb'}" data-select="${esc(s.id||s.owner||'')}"></button>`).join('')}</div><p class="sub">Overview is proportional. Detailed boxes below are enlarged for readability.</p><div class="stats"><span><b>${fmt(active)}</b>Active allocation</span><span><b>${fmt(reserved)}</b>Reserved</span><span><b>${fmt(root.size-active-reserved)}</b>Unallocated</span></div><div class="toolbar"><div class="legend"><span>Active</span><span class="reserve">Reserved</span><span class="free">Unallocated</span></div><label style="margin-left:auto"><input type="checkbox" id="showReserve" ${expanded?'checked':''}> Expand reservations</label></div><div class="map">${segs.filter(s=>s.status!=='growth').map(s=>{let r=segs.find(r=>r.owner===s.id);return `<div class="allocation ${s.id===selected?'chosen':''}">${box(s)}${r?(expanded||s.id===selected?box(r):`<button class="range growth" data-select="${esc(s.id)}"><span class="range-mid">↳ Growth space reserved <code>+${fmt(r.end-r.start+1)} addresses</code></span></button>`):''}</div>`}).join('')}</div></div><aside class="panel inspector" id="inspector"></aside></div><details class="panel"><summary>Campus hierarchy & building view</summary><p>The diagram above groups by network function, following the worked solution. This is a logical allocation map, not a physical router/link topology. Buildings can have allocations in several pools.</p>${plan.campus?`<div class="callout"><strong>${esc(plan.campus.name)} · ${esc(plan.campus.cidr)}</strong>${addr(subnet(plan.campus.cidr).start)} → ${addr(subnet(plan.campus.cidr).end)}<br>${esc(plan.campus.poolIds.map(id=>plan.pools.find(p=>p.id===id).name).join(' · '))}<br>Space outside these pools remains unallocated. Public DMZ addresses are separate from this private container.</div>`:''}<div class="toolbar"><label>Filter by location <select id="location"><option>All locations</option>${locations.map(l=>`<option ${location===l?'selected':''}>${esc(l)}</option>`).join('')}</select></label></div><div class="location-grid">${plan.pools.flatMap(p=>p.allocations.filter(a=>location==='All locations'||a.location===location).map(a=>`<button data-jump="${esc(a.id)}" data-parent="${esc(p.id)}"><b>${esc(a.name)}</b><code>${esc(a.cidr)}</code></button>`)).join('')}</div></details>`;
$('#explore').querySelectorAll('[data-pool]').forEach(b=>b.onclick=()=>{poolId=b.dataset.pool;selected=null;render()});$('#explore').querySelectorAll('[data-select]').forEach(b=>b.onclick=()=>{if(!b.dataset.select)return;selected=b.dataset.select;let scroll=$('.map').scrollTop;render();$('.map').scrollTop=scroll});$('#showReserve').onchange=e=>{expanded=e.target.checked;render()};$('#location').onchange=e=>{location=e.target.value;render();$('#location').closest('details').open=true};$('#explore').querySelectorAll('[data-jump]').forEach(b=>b.onclick=()=>{poolId=b.dataset.parent;selected=b.dataset.jump;render();$('#explore').scrollIntoView({behavior:'smooth'})});inspect(a,pool);}
function box(s){return `<button class="range ${s.status}" data-select="${esc(s.id||s.owner||'')}"><span class="range-top">${addr(s.start)}<small>${s.status==='growth'?'Growth reservation':s.status}</small></span><span class="range-mid"><b>${esc(s.name)}</b><code>${esc(s.cidr||fmt(s.end-s.start+1)+' addresses')}</code></span><span class="range-bottom">${addr(s.end)}<span>${fmt(s.end-s.start+1)} addresses</span></span></button>`}
function inspect(a,pool){if(!a){$('#inspector').innerHTML='<h2>No allocations yet</h2><p>The entire pool is unallocated. Add an allocation in your JSON plan.</p>';return}let n=subnet(a.cidr),e=envelope(a),growth=e.size>n.size;$('#inspector').innerHTML=`<div class="kicker">ALLOCATION INSPECTOR</div><h2>${esc(a.name)}</h2><p class="sub">${esc(a.location)} · ${esc(a.status)}</p><div class="big-cidr">${esc(a.cidr)}</div><div class="metrics">${metric(fmt(n.size),'total addresses')}${metric(fmt(n.usable),n.p<31?'usable if one conventional LAN':n.p===31?'addresses on a /31 point-to-point link':'single host address')}</div><dl>${detail('Subnet mask',n.mask)}${detail('First address / network',addr(n.start))}${detail(n.p<31?'Last address / broadcast':'Last address',addr(n.end))}${detail(n.p<31?'Usable host range':'Address range',addr(n.start+(n.p<31?1:0))+' – '+addr(n.end-(n.p<31?1:0)))}${detail('Required hosts',a.requiredHosts?fmt(a.requiredHosts):'Not specified')}${detail('Host bits','32 − '+n.p+' = '+(32-n.p))}</dl><div class="callout"><strong>Why /${n.p}?</strong>2<sup>${32-n.p}</sup> = ${fmt(n.size)} addresses.${n.p<31?` Subtract network and broadcast: ${fmt(n.size)} − 2 = ${fmt(n.usable)} usable hosts.`:' /31 point-to-point and /32 host routes are exceptions to subtracting two.'}${a.requiredHosts?` Demand: ${fmt(a.requiredHosts)}. ${a.requiredHosts>(n.size/2-2)?'The next smaller block would not fit.':'A smaller block may fit; allocation can also reflect a planning policy.'}`:' This is an allocation decision, not a measured host demand.'}</div>${growth?`<details open><summary>Leave room to grow</summary><p>Keep <b>${addr(n.end+1)}/${n.p}</b> unused for this network. The two aligned sibling blocks combine into <b>${e.cidr}</b>.</p><div class="split-demo" id="growthDemo"><div>Active<br><code>/${n.p}</code></div><div>Reserved<br><code>/${n.p}</code></div></div><button id="merge" class="dark">↔ Preview expansion to /${e.p}</button><p id="mergeText" class="sub" aria-live="polite">Reservation is a planning promise, not an active subnet.</p></details>`:`<details><summary>How this allocation can grow</summary><p>${a.status==='reserved'?'This entire slot is reserved for a future allocation. It is not currently configured.':'No adjacent growth block is promised in this plan. An additional allocation may be needed later.'} Institute blocks may be subdivided into smaller networks; usable capacity then depends on that subdivision.</p></details>`}<details><summary>Binary: where the network ends</summary><p><b>First ${n.p} bits:</b> network prefix. <b>Last ${32-n.p} bits:</b> addresses within the block. A valid network address has all host bits zero.</p>${binaryAddress(n.start,n.p)}</details>`;if(growth)$('#merge').onclick=()=>{let merged=$('#growthDemo').classList.toggle('merged');$('#merge').textContent=merged?'↶ Reset preview':'↔ Preview expansion to /'+e.p;$('#mergeText').textContent=merged?`${e.cidr}: ${fmt(e.size)} total, ${fmt(e.usable)} usable. Range: ${addr(e.start)} – ${addr(e.end)}. This preview does not change the plan. Expanding a real subnet also requires mask, routing and DHCP changes.`:'Reservation is a planning promise, not an active subnet.'}}
function calculate(){let a=plan.pools.flatMap(p=>p.allocations).find(a=>a.id===selected),c=a?.cidr||plan.pools[0].cidr;$('#calculate').innerHTML=`<div class="heading"><div><h2>Move the boundary. Watch the space change.</h2><p class="sub">One extra network bit halves the block. One fewer bit doubles it.</p></div><span class="tag">SANDBOX · DOES NOT EDIT PLAN</span></div><div class="grid-two" style="margin-top:22px"><div class="panel"><div class="form-grid"><label>IPv4 address<input id="calcIP" value="${esc(c.split('/')[0])}"></label><label>Prefix length<input type="number" id="prefixNumber" min="0" max="32" value="${c.split('/')[1]}"></label></div><input aria-label="Prefix length slider" type="range" id="prefix" min="0" max="32" value="${c.split('/')[1]}"><div id="calcResult" aria-live="polite"></div></div><div class="panel"><div class="kicker">SIZE IT FROM DEMAND</div><h2>How much space do you need?</h2><p class="sub">Enter all interfaces that need addresses, including the gateway. Conventional IPv4 LAN sizing, up to /30.</p><label style="margin-top:20px">Required usable addresses<input type="number" id="hosts" value="1022" min="1" max="4294967294"></label><div id="hostResult" aria-live="polite"></div><details open><summary>Why leave a gap next door?</summary><p>Free space somewhere in the pool is not enough. To grow without renumbering, you need the correct aligned sibling block. For example, two /22 blocks can become a /21 only at a /21 boundary.</p><p>Allocate larger blocks first to reduce fragmentation, then reserve each block’s aligned neighbour. Reservations do not configure router interfaces or enforce security.</p></details><details><summary>Why not just use one huge subnet?</summary><p>Separate networks support routing and policy boundaries. Isolation still needs routing/firewall rules. A giant broadcast domain can add operational and broadcast overhead. The course uses larger client-isolated Wi-Fi networks and separate wired networks (pp. 24–27).</p></details></div></div>`;const update=()=>{try{let p=Number($('#prefixNumber').value);if(!Number.isInteger(p)||p<0||p>32)throw Error('Prefix must be an integer from 0 to 32.');$('#prefix').value=p;let n=subnet($('#calcIP').value+'/'+p);$('#calcResult').innerHTML=`<div class="big-cidr">${n.cidr}</div>${!n.aligned?`<div class="callout amber"><strong>That is a host address, not this network’s start.</strong>The containing block starts at ${addr(n.start)}. Host bits are cleared to find the network.</div>`:''}<div class="metrics">${metric(fmt(n.size),'total addresses')}${metric(fmt(n.usable),p<31?'usable hosts':p===31?'point-to-point addresses':'host route')}</div><dl>${detail('Mask',n.mask)}${detail('Network',addr(n.start))}${detail(p<31?'Broadcast':'Last address',addr(n.end))}${detail('Host bits',32-p)}</dl>${binaryAddress(ip($('#calcIP').value),p)}<p class="sub">Purple: ${p} network bits · Green: ${32-p} host bits<br>${p<31?'Usable hosts = 2^(32 − prefix) − 2.':'/31 is for point-to-point links (RFC 3021); /32 identifies one address. No conventional network/broadcast subtraction.'}</p>`}catch(e){$('#calcResult').textContent=e.message}};$('#prefix').oninput=e=>{$('#prefixNumber').value=e.target.value;update()};$('#prefixNumber').oninput=update;$('#calcIP').oninput=update;$('#hosts').oninput=()=>{let h=Number($('#hosts').value);if(!Number.isInteger(h)||h<1||h>4294967294){$('#hostResult').textContent='Enter an integer from 1 to 4,294,967,294.';return}let bits=Math.max(2,Math.ceil(Math.log2(h+2))),p=32-bits;$('#hostResult').innerHTML=`<div class="callout"><strong>Smallest conventional LAN: /${p}</strong>${fmt(h)} + 2 = ${fmt(h+2)} required addresses.<br>Round up to 2<sup>${bits}</sup> = ${fmt(2**bits)}.<br>32 − ${bits} = /${p} → ${fmt(2**bits-2)} usable hosts.<br>${fmt(2**bits-2-h)} usable addresses remain after demand.</div><p class="sub" style="margin-top:14px">${p>0?`To reserve one doubling, plan an aligned /${p-1} envelope with ${fmt(2**(bits+1))} total addresses.`:'This fills all IPv4 space; no larger IPv4 envelope exists.'}</p>`};update();$('#hosts').oninput()}
let qIndex=0,answered=false,score=0;function questions(){let a=plan.pools.flatMap(p=>p.allocations).find(a=>a.growthPrefix!==undefined)||plan.pools[0].allocations[0];if(!a)return[];let n=subnet(a.cidr),e=envelope(a);return [{q:`How many total addresses are in ${a.cidr}?`,answer:String(n.size),hint:`There are 32 − ${n.p} host bits.`,why:`2^${32-n.p} = ${fmt(n.size)} total addresses. Total space includes every address, not just usable hosts.`},{q:`What is the last address in ${a.cidr}?`,answer:addr(n.end),hint:'Start + block size − 1. Remember to carry across octets.',why:`${addr(n.start)} + ${n.size-1} = ${addr(n.end)}.${n.p<31?' On a conventional LAN, this is the broadcast address.':''}`},{q:a.growthPrefix!==undefined?`Which CIDR contains ${a.cidr} plus its reserved growth block?`:`What is the subnet mask for ${a.cidr}?`,answer:a.growthPrefix!==undefined?e.cidr:n.mask,hint:a.growthPrefix!==undefined?'Doubling the block removes one prefix bit.':'Network bits are 1; host bits are 0.',why:a.growthPrefix!==undefined?`${e.cidr} covers both aligned halves. A random adjacent block cannot always be merged.`:`/${n.p} has ${n.p} leading ones: ${n.mask}.`}]}
function practice(){let qs=questions();if(!qs.length){$('#practice').innerHTML='<div class="panel">Add an allocation to your plan to generate practice questions.</div>';return}qIndex=Math.min(qIndex,qs.length-1);let q=qs[qIndex];$('#practice').innerHTML=`<div class="grid-two"><div class="panel"><div class="kicker">RETRIEVE BEFORE YOU REVEAL · ${qIndex+1} / ${qs.length}</div><h2>${esc(q.q)}</h2><p class="sub">Questions use the currently loaded plan.</p><form id="answerForm"><label style="margin:22px 0">Your answer<input id="answer" autocomplete="off" placeholder="Enter a number, address or CIDR" required></label><button class="dark">Check answer</button> <button type="button" id="hint">Give me a hint</button></form><div class="feedback" id="feedback" aria-live="polite"></div><button id="next">${qIndex===qs.length-1?'Start again':'Next question →'}</button></div><div class="panel"><h2>Think like a network planner.</h2><details open><summary>1. Count the interfaces</summary><p>Estimate hosts for each separate network. Include gateway addresses and any infrastructure sharing the subnet.</p></details><details open><summary>2. Round up, then align</summary><p>Choose a power-of-two block that fits the demand. Its start must be a multiple of its block size in the 32-bit address space.</p></details><details open><summary>3. Reserve with a purpose</summary><p>Protect the correct sibling for growth. Record which allocation owns the reservation, so another subnet does not consume it.</p></details><details><summary>4. Check the whole plan</summary><p>Verify containment, non-overlap, capacity and growth reservations, then document assumptions. A valid address plan alone does not prove routing or security is correct.</p></details></div></div>`;answered=false;$('#answerForm').onsubmit=ev=>{ev.preventDefault();let correct=$('#answer').value.trim()===q.answer;$('#feedback').textContent=correct?'✓ Correct. '+q.why:'Not yet. '+q.hint;answered=correct};$('#hint').onclick=()=>{$('#feedback').textContent=q.hint+' Try once more before checking the explorer.'};$('#next').onclick=()=>{qIndex=(qIndex+1)%qs.length;practice()}}
function guide(){$('#guide').innerHTML=`<div class="grid-two"><div class="panel"><h2>A plan you can take apart.</h2><p style="line-height:1.8">All network values come from a loaded JSON file. Address ranges, masks, capacities, free gaps and growth reservations are calculated from CIDR prefixes. Upload your own plan to use the same explorer and exercises.</p><div class="file-links"><a href="ost-campus.json" download>↓ OST example</a><a href="network-plan.schema.json" download>↓ JSON Schema</a><a href="CONFIG.md" download>↓ Format guide</a></div><details open><summary>Format & interoperability</summary><p>JSON is the interchange format; JSON Schema Draft 2020-12 describes its structure. CIDR is standard network notation. The surrounding plan schema is specific to this learning app: it is not a NetBox export, YANG model or device configuration. JSON Schema validates structure; the app additionally validates address semantics.</p></details><pre>${esc(JSON.stringify({version:1,name:'My network',pools:[{id:'lan',name:'Local networks',cidr:'192.168.0.0/16',allocations:[{id:'office',name:'Office',cidr:'192.168.0.0/24',requiredHosts:100,location:'Building A',status:'active',growthPrefix:23}]}]},null,2))}</pre><p class="sub">Uploads stay in this browser tab. Nothing is sent to a server. Maximum file size: 1 MB. Refresh restores the OST example; export to keep your plan. IPv4 only.</p><button id="resetPlan" style="margin-top:16px">Restore OST plan</button></div><div class="panel"><h2>Sources, assumptions & corrections</h2><p class="sub">The supplied PDF is authoritative, with inconsistencies made explicit.</p><ul class="notes">${(plan.sourceNotes||['Custom uploaded plan. Its provenance is supplied by its author; validation checks address consistency, not factual accuracy.']).map(n=>`<li>${esc(n)}</li>`).join('')}</ul><details><summary>Beyond this IPv4 lab: IPv6</summary><p>The course uses /64 IPv6 LANs and a /48 campus allocation, yielding 2^(64−48) = 65,536 /64 subnets. Plan by network purpose and location, not by IPv4 host counts. IPv6 does not use broadcast, so the IPv4 “subtract two” rule does not transfer. See course pp. 35–37. This app intentionally validates only IPv4 plans.</p></details><div class="file-links"><a href="https://www.rfc-editor.org/rfc/rfc4632.html" target="_blank" rel="noreferrer">CIDR · RFC 4632 ↗</a><a href="https://www.rfc-editor.org/rfc/rfc3021.html" target="_blank" rel="noreferrer">/31 links · RFC 3021 ↗</a><a href="https://json-schema.org/draft/2020-12" target="_blank" rel="noreferrer">JSON Schema ↗</a></div></div></div>`;$('#resetPlan').onclick=async()=>{setPlan(await(await fetch('ost-campus.json')).json());$('#notice').textContent='OST example restored.';setTab('explore')}}
$('#importBtn').onclick=()=>{if(config.components.importPlan)$('#upload').click()};$('#upload').onchange=async e=>{if(!config.components.importPlan)return;try{let f=e.target.files[0];if(!f)return;if(f.size>1e6)throw Error('Maximum upload size is 1 MB.');let p=JSON.parse(await f.text());setPlan(p);$('#notice').textContent='Plan loaded. CIDR alignment, capacity, containment and reservation overlaps checked.';setTab('explore')}catch(err){$('#notice').textContent='Plan not loaded: '+err.message+' Your previous plan is unchanged.'}e.target.value=''};$('#exportBtn').onclick=()=>{if(!config.components.exportPlan)return;let blob=new Blob([JSON.stringify(plan,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='network-plan.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
try {
  const response = await fetch('app-config.json', {cache: 'no-store'});
  if (!response.ok) throw Error(`HTTP ${response.status}`);
  config = deploymentConfig(await response.json());
} catch (error) {
  // A deployment typo must not break unrelated learning tools.
  $('#notice').textContent = 'App configuration could not be loaded; using all components enabled. ' + error.message;
}
document.querySelectorAll('nav button').forEach(button => {button.hidden = !config.tabs[button.dataset.tab];});
$('#importBtn').hidden = !config.components.importPlan;
$('#exportBtn').hidden = !config.components.exportPlan;
if (!enabledTab(config, tab)) $('#notice').textContent = 'No learning sections are enabled in this deployment.';
try{setPlan(await(await fetch('ost-campus.json')).json())}catch(e){$('#notice').textContent='Unable to load default plan: '+e.message}
